import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authAPI } from '../services/api';

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);
    try {
      await authAPI.register({
        username: formData.username,
        email: formData.email,
        password: formData.password,
      });
      navigate('/login', { state: { message: 'Registration successful. Please log in.' } });
    } catch (err) {
      setError(err.response?.data?.detail || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  const passwordStrength = formData.password.length >= 8 ? 'medium' : 'weak';

  return (
    <main className="flex-grow flex items-center justify-center px-gutter py-xl">
      <div className="w-full max-w-[480px]">
        <div className="mb-xl text-center">
          <h1 className="font-headline-lg text-headline-lg text-primary mb-xs">AgroLens</h1>
          <p className="font-body-md text-body-md text-on-surface-variant">
            Precision diagnostics for a sustainable future.
          </p>
        </div>

        <div className="bg-surface border border-outline-variant rounded-xl p-lg md:p-xl shadow-sm">
          <header className="mb-lg">
            <h2 className="font-title-md text-title-md text-on-surface mb-xs">
              Create an Account
            </h2>
            <p className="font-label-md text-label-md text-on-surface-variant">
              Join our community of precision agronomists.
            </p>
          </header>

          {error && (
            <div className="mb-lg bg-error-container border border-error/20 p-md rounded-lg flex items-start gap-md">
              <span className="material-symbols-outlined text-error">error</span>
              <p className="text-on-error-container text-body-md">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5">

  {/* Username */}
  <div>
    <label
      htmlFor="username"
      className="block mb-2 text-sm font-semibold text-gray-700"
    >
      Username
    </label>

    <div className="relative">
      <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-[22px] pointer-events-none">
        person
      </span>

      <input
        id="username"
        name="username"
        type="text"
        value={formData.username}
        onChange={handleChange}
        placeholder="johndoe_agri"
        required
        className="w-full h-14 rounded-xl border border-gray-300 bg-white pl-14 pr-4 text-gray-800 placeholder:text-gray-400 outline-none transition-all focus:border-green-600 focus:ring-2 focus:ring-green-100"
      />
    </div>
  </div>

  {/* Email */}
  <div>
    <label
      htmlFor="email"
      className="block mb-2 text-sm font-semibold text-gray-700"
    >
      Email Address
    </label>

    <div className="relative">
      <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-[22px] pointer-events-none">
        mail
      </span>

      <input
        id="email"
        name="email"
        type="email"
        value={formData.email}
        onChange={handleChange}
        placeholder="name@example.com"
        required
        className="w-full h-14 rounded-xl border border-gray-300 bg-white pl-14 pr-4 text-gray-800 placeholder:text-gray-400 outline-none transition-all focus:border-green-600 focus:ring-2 focus:ring-green-100"
      />
    </div>
  </div>

  {/* Password */}
  <div>
    <label
      htmlFor="password"
      className="block mb-2 text-sm font-semibold text-gray-700"
    >
      Password
    </label>

    <div className="relative">
      <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-[22px] pointer-events-none">
        lock
      </span>

      <input
        id="password"
        name="password"
        type={showPassword ? 'text' : 'password'}
        value={formData.password}
        onChange={handleChange}
        placeholder="••••••••"
        required
        className="w-full h-14 rounded-xl border border-gray-300 bg-white pl-14 pr-4 text-gray-800 placeholder:text-gray-400 outline-none transition-all focus:border-green-600 focus:ring-2 focus:ring-green-100"
      />
    </div>
  </div>

  {/* Confirm Password */}
  <div>
    <label
      htmlFor="confirmPassword"
      className="block mb-2 text-sm font-semibold text-gray-700"
    >
      Confirm Password
    </label>

    <div className="relative">
      <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-[22px] pointer-events-none">
        lock_reset
      </span>

      <input
        id="confirmPassword"
        name="confirmPassword"
        type={showPassword ? 'text' : 'password'}
        value={formData.confirmPassword}
        onChange={handleChange}
        placeholder="••••••••"
        required
        className="w-full h-14 rounded-xl border border-gray-300 bg-white pl-14 pr-4 text-gray-800 placeholder:text-gray-400 outline-none transition-all focus:border-green-600 focus:ring-2 focus:ring-green-100"
      />
    </div>
  </div>

</form>

          <div className="mt-lg pt-lg border-t border-outline-variant text-center">
            <p className="font-body-md text-body-md text-on-surface-variant">
              Already have an account?{' '}
              <Link to="/login" className="text-primary font-bold hover:underline transition-all">
                Login
              </Link>
            </p>
          </div>
        </div>

        <div className="mt-xl flex flex-wrap justify-center gap-lg">
          <div className="flex items-center gap-xs opacity-60">
            <span className="material-symbols-outlined text-on-surface-variant">verified_user</span>
            <span className="font-label-md text-caption uppercase tracking-wider text-on-surface-variant">
              Secure Data
            </span>
          </div>
          <div className="flex items-center gap-xs opacity-60">
            <span className="material-symbols-outlined text-on-surface-variant">biotech</span>
            <span className="font-label-md text-caption uppercase tracking-wider text-on-surface-variant">
              Precision AI
            </span>
          </div>
        </div>
      </div>
    </main>
  );
};

export default Register;
